"use strict";(globalThis.webpackChunkdoqumentation=globalThis.webpackChunkdoqumentation||[]).push([[3867],{67819(e,a,o){o.r(a),o.d(a,{assets:()=>t,contentTitle:()=>r,default:()=>d,frontMatter:()=>i,metadata:()=>n,toc:()=>l});const n=JSON.parse('{"id":"learning/courses/quantum-computing-in-practice/introduction","title":"Introducci\xf3n","description":"Un curso gratuito de IBM sobre computaci\xf3n cu\xe1ntica a escala de utilidad con casos de uso realistas y mejores pr\xe1cticas","source":"@site/i18n/es/docusaurus-plugin-content-docs/current/learning/courses/quantum-computing-in-practice/introduction.mdx","sourceDirName":"learning/courses/quantum-computing-in-practice","slug":"/learning/courses/quantum-computing-in-practice/introduction","permalink":"/learning/courses/quantum-computing-in-practice/introduction","draft":false,"unlisted":false,"editUrl":"https://github.com/JanLahmann/doQumentation/tree/main/docs/learning/courses/quantum-computing-in-practice/introduction.mdx","tags":[],"version":"current","frontMatter":{"title":"Introducci\xf3n","sidebar_label":"Introducci\xf3n","description":"Un curso gratuito de IBM sobre computaci\xf3n cu\xe1ntica a escala de utilidad con casos de uso realistas y mejores pr\xe1cticas","notebook_path":"learning/courses/quantum-computing-in-practice/introduction.ipynb"},"sidebar":"tutorialsSidebar","previous":{"title":"Descripci\xf3n general","permalink":"/learning/courses/quantum-computing-in-practice/"},"next":{"title":"Ejecuci\xf3n de circuitos cu\xe1nticos","permalink":"/learning/courses/quantum-computing-in-practice/running-quantum-circuits"}}');var s=o(74848),c=o(28453);const i={title:"Introducci\xf3n",sidebar_label:"Introducci\xf3n",description:"Un curso gratuito de IBM sobre computaci\xf3n cu\xe1ntica a escala de utilidad con casos de uso realistas y mejores pr\xe1cticas",notebook_path:"learning/courses/quantum-computing-in-practice/introduction.ipynb"},r="Introducci\xf3n al curso {#course-introduction}",t={},l=[{value:"Acerca de este curso",id:"about-this-course",level:2},{value:"Quantum Utility",id:"quantum-utility",level:3},{value:"Simulaci\xf3n de la naturaleza",id:"simulating-nature",level:3},{value:"Enfoque en procesadores cu\xe1nticos m\xe1s grandes",id:"a-focus-on-larger-quantum-processors",level:3},{value:"P\xfablico objetivo y objetivos del curso",id:"audience-and-course-goals",level:3},{value:"La historia de la computaci\xf3n",id:"the-story-of-computation",level:2},{value:"Dispositivos de c\xe1lculo desde la antig\xfcedad",id:"computing-devices-since-ancient-times",level:3},{value:"Conexiones con el mundo f\xedsico",id:"connections-to-the-physical-world",level:3},{value:"Ley de Moore",id:"moores-law",level:3},{value:"Computaci\xf3n cu\xe1ntica",id:"quantum-computing",level:2},{value:"Mec\xe1nica cu\xe1ntica y computaci\xf3n",id:"quantum-mechanics-and-computation",level:3},{value:"Computaci\xf3n cu\xe1ntica en la teor\xeda",id:"quantum-computing-in-theory",level:3},{value:"Computaci\xf3n cu\xe1ntica en la pr\xe1ctica",id:"quantum-computing-in-practice",level:3},{value:"Aplicaciones potenciales",id:"potential-applications",level:3},{value:"Estado de la tecnolog\xeda",id:"state-of-the-technology",level:3},{value:"Conclusi\xf3n",id:"conclusion",level:2}];function u(e){const a={a:"a",em:"em",h1:"h1",h2:"h2",h3:"h3",header:"header",li:"li",p:"p",strong:"strong",ul:"ul",...(0,c.R)(),...e.components},{IBMVideo:o}=a;return o||function(e,a){throw new Error("Expected "+(a?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}("IBMVideo",!0),(0,s.jsxs)(s.Fragment,{children:["\n",(0,s.jsx)(a.header,{children:(0,s.jsx)(a.h1,{id:"course-introduction",children:"Introducci\xf3n al curso"})}),"\n",(0,s.jsxs)(a.p,{children:["Haz clic a continuaci\xf3n para escuchar una introducci\xf3n al curso de Olivia Lanes, o abre el video en una ventana separada en ",(0,s.jsx)(a.a,{href:"https://youtube.com/watch?v=sVRpKhCfKRI",children:"YouTube."})]}),"\n",(0,s.jsx)(o,{id:"134063425",title:"En este video, Olivia Lanes ofrece una visi\xf3n general de la computaci\xf3n cu\xe1ntica pr\xe1ctica en la era de la utilidad. Aborda el p\xfablico objetivo y algunos antecedentes sobre temas como la Ley de Moore y los fundamentos te\xf3ricos de la computaci\xf3n cu\xe1ntica."}),"\n",(0,s.jsx)(a.h2,{id:"about-this-course",children:"Acerca de este curso"}),"\n",(0,s.jsxs)(a.p,{children:["Bienvenido a ",(0,s.jsx)(a.em,{children:"Quantum Computing in Practice"})," -- un curso que se centra en los computadores cu\xe1nticos de hoy y en c\xf3mo aprovecharlos al m\xe1ximo.\nCubre casos de uso potenciales realistas de la computaci\xf3n cu\xe1ntica, as\xed como mejores pr\xe1cticas para operar y experimentar con procesadores cu\xe1nticos de 100 o m\xe1s qubits."]}),"\n",(0,s.jsx)(a.h3,{id:"quantum-utility",children:"Quantum Utility"}),"\n",(0,s.jsxs)(a.p,{children:["Es un momento emocionante para la computaci\xf3n cu\xe1ntica.\nDespu\xe9s de muchos a\xf1os de investigaci\xf3n y desarrollo te\xf3rico y experimental, los computadores cu\xe1nticos se acercan a un punto en el que pueden empezar a competir con los computadores cl\xe1sicos y demostrar ",(0,s.jsx)(a.em,{children:"utilidad"}),"."]}),"\n",(0,s.jsxs)(a.p,{children:["La utilidad no es lo mismo que la ",(0,s.jsx)(a.em,{children:"ventaja cu\xe1ntica"}),", que se refiere a que los computadores cu\xe1nticos ",(0,s.jsx)(a.em,{children:"superen"})," a los computadores cl\xe1sicos en tareas significativas.\nLos computadores cl\xe1sicos tienen un rendimiento y una adaptabilidad incre\xedbles, y la realidad es que los computadores cu\xe1nticos a\xfan no pueden superarlos.\nHemos visto d\xe9cadas de avances en la computaci\xf3n cl\xe1sica -- no solo en hardware de computaci\xf3n, sino tambi\xe9n en algoritmos para computadores cl\xe1sicos -- y podemos ver claramente que la tecnolog\xeda de la computaci\xf3n digital electr\xf3nica ha transformado profundamente nuestro mundo."]}),"\n",(0,s.jsxs)(a.p,{children:["La computaci\xf3n cu\xe1ntica, por otro lado, se encuentra en una fase diferente de desarrollo.\nLa computaci\xf3n cu\xe1ntica impone demandas extremas a nuestro control de sistemas de mec\xe1nica cu\xe1ntica y empuja los l\xedmites de la tecnolog\xeda actual -- y no podemos esperar de manera realista dominar esta nueva tecnolog\xeda y superar la computaci\xf3n cl\xe1sica directamente desde el inicio.\nPero estamos viendo se\xf1ales que sugieren que los computadores cu\xe1nticos est\xe1n comenzando a ser competitivos con los m\xe9todos de computaci\xf3n cl\xe1sica para tareas seleccionadas, lo cual es un paso natural en el desarrollo tecnol\xf3gico de la computaci\xf3n cu\xe1ntica, conocido como ",(0,s.jsx)(a.em,{children:"Quantum Utility"}),"."]}),"\n",(0,s.jsx)(a.p,{children:"A medida que la tecnolog\xeda avanza y se desarrollan nuevos m\xe9todos para la computaci\xf3n cu\xe1ntica, podemos esperar razonablemente que sus ventajas se vuelvan cada vez m\xe1s pronunciadas -- pero eso tomar\xe1 tiempo.\nCuando eso suceda, probablemente veremos una interacci\xf3n con la computaci\xf3n cl\xe1sica:\nse realizar\xe1n demostraciones de computaci\xf3n cu\xe1ntica y la computaci\xf3n cl\xe1sica responder\xe1, la computaci\xf3n cu\xe1ntica dar\xe1 otro paso, y el patr\xf3n se repetir\xe1.\nY alg\xfan d\xeda, cuando el rendimiento de un computador cu\xe1ntico ya no pueda ser alcanzado cl\xe1sicamente, sospecharemos que hemos visto una ventaja cu\xe1ntica -- pero incluso entonces no lo sabremos con certeza.\nDemostrar resultados de imposibilidad para los computadores cl\xe1sicos es, hasta donde sabemos, un problema imposiblemente dif\xedcil en s\xed mismo."}),"\n",(0,s.jsx)(a.h3,{id:"simulating-nature",children:"Simulaci\xf3n de la naturaleza"}),"\n",(0,s.jsx)(a.p,{children:"Los simuladores cl\xe1sicos -- es decir, programas inform\xe1ticos en computadores cl\xe1sicos que simulan sistemas f\xedsicos -- pueden hacer predicciones sobre sistemas de mec\xe1nica cu\xe1ntica.\nPero los simuladores cl\xe1sicos no son mec\xe1nico-cu\xe1nticos y no pueden emular directamente sistemas de mec\xe1nica cu\xe1ntica.\nEn su lugar, utilizan c\xe1lculos matem\xe1ticos para aproximar el comportamiento mec\xe1nico-cu\xe1ntico.\nA medida que crece el tama\xf1o de los sistemas simulados, el esfuerzo requerido aumenta dr\xe1sticamente, lo que establece l\xedmites sobre qu\xe9 sistemas cu\xe1nticos pueden simularse cl\xe1sicamente, cu\xe1nto tiempo tardan las simulaciones y cu\xe1n precisos son los resultados."}),"\n",(0,s.jsx)(a.p,{children:"Los computadores cu\xe1nticos, por otro lado, pueden emular sistemas cu\xe1nticos m\xe1s directamente -- y como resultado, el esfuerzo que requieren escala considerablemente mejor a medida que crece el tama\xf1o del sistema.\nEsta fue de hecho la idea de Richard Feynman en la d\xe9cada de 1980, que motiv\xf3 por primera vez una investigaci\xf3n del potencial de los computadores cu\xe1nticos.\n\xa1Hablaremos m\xe1s sobre esto m\xe1s adelante!"}),"\n",(0,s.jsx)(a.p,{children:"Investigadores de IBM\xae publicaron un art\xedculo en 2023 que mostr\xf3 por primera vez que un computador cu\xe1ntico puede competir con t\xe9cnicas cl\xe1sicas de vanguardia para simular un modelo f\xedsico particular.\nSus resultados a\xfan pueden ser alcanzados por t\xe9cnicas avanzadas en computadores cl\xe1sicos -- pero super\xf3 a los algoritmos de fuerza bruta,\ny tambi\xe9n ofrece un nuevo punto de datos con el cual se pueden comparar diferentes m\xe9todos de simulaci\xf3n (que no son exactos y no todos coinciden en sus predicciones)."}),"\n",(0,s.jsx)(a.h3,{id:"a-focus-on-larger-quantum-processors",children:"Enfoque en procesadores cu\xe1nticos m\xe1s grandes"}),"\n",(0,s.jsx)(a.p,{children:"Los usuarios anteriores de hardware cu\xe1ntico de IBM pueden haber notado que los procesadores m\xe1s peque\xf1os que anteriormente pon\xedamos a disposici\xf3n del p\xfablico han sido retirados para dar paso a procesadores m\xe1s grandes (con m\xe1s de 100 qubits).\nEstos procesadores m\xe1s peque\xf1os pod\xedan ser f\xe1cilmente simulados cl\xe1sicamente.\nAunque representaban pasos intermedios accesibles al p\xfablico en una tecnolog\xeda en progreso, no pod\xedan demostrar Quantum Utility: todo lo que se pod\xeda hacer con ellos podr\xeda haberse hecho igualmente f\xe1cil con una simulaci\xf3n cl\xe1sica."}),"\n",(0,s.jsxs)(a.p,{children:["Con aproximadamente 100 qubits, sin embargo, eso ya no es el caso. En general, los procesadores cu\xe1nticos de este tama\xf1o ya no pueden ser simulados cl\xe1sicamente.\nEsto representa una especie de transici\xf3n de fase -- hacia una nueva era de la tecnolog\xeda de computaci\xf3n cu\xe1ntica, en la que el ",(0,s.jsx)(a.em,{children:"potencial"})," para superar los c\xe1lculos cl\xe1sicos existe.\nAqu\xed es donde IBM ha decidido concentrarse -- para buscar rendimiento computacional cu\xe1ntico y trabajar hacia una eventual ventaja cu\xe1ntica."]}),"\n",(0,s.jsx)(a.p,{children:"Animamos a nuestros usuarios a aprovechar al m\xe1ximo estos nuevos dispositivos, experimentar con ellos, probar sus l\xedmites y aprender de las experiencias para la pr\xf3xima generaci\xf3n de procesadores cu\xe1nticos, que actualmente est\xe1 en desarrollo.\n\xa1Este curso est\xe1 dise\xf1ado para permitirte hacer exactamente eso!"}),"\n",(0,s.jsx)(a.h3,{id:"audience-and-course-goals",children:"P\xfablico objetivo y objetivos del curso"}),"\n",(0,s.jsx)(a.p,{children:"Este curso est\xe1 dirigido a cualquier persona que quiera desarrollar nuevas aplicaciones para computadores cu\xe1nticos, escalar su trabajo actual en computaci\xf3n cu\xe1ntica o aprender a incorporar procesadores cu\xe1nticos en su flujo de trabajo.\nEsto incluye no solo a f\xedsicos e inform\xe1ticos, sino tambi\xe9n a ingenieros, qu\xedmicos, cient\xedficos de materiales y cualquier otra persona con inter\xe9s en dominar el hardware de computaci\xf3n cu\xe1ntica."}),"\n",(0,s.jsx)(a.p,{children:"El curso ser\xe1 pr\xe1ctico y se centrar\xe1 en el uso pr\xe1ctico de los computadores cu\xe1nticos.\nEntre otros, se cubrir\xe1n los siguientes temas y habilidades:"}),"\n",(0,s.jsxs)(a.ul,{children:["\n",(0,s.jsx)(a.li,{children:"Ejecuci\xf3n de trabajos a escala de utilidad en procesadores cu\xe1nticos a trav\xe9s de Qiskit Runtime"}),"\n",(0,s.jsx)(a.li,{children:"Uso de t\xe9cnicas de mitigaci\xf3n de errores para mejorar los resultados del hardware"}),"\n",(0,s.jsx)(a.li,{children:"\xc1reas de aplicaci\xf3n potenciales para los computadores cu\xe1nticos a corto plazo"}),"\n"]}),"\n",(0,s.jsxs)(a.p,{children:["Este curso no cubre la teor\xeda introductoria de la computaci\xf3n cu\xe1ntica y asume conocimientos b\xe1sicos sobre qubits y circuitos cu\xe1nticos.\nEl curso ",(0,s.jsx)(a.em,{children:"Basics of Quantum Information"})," en esta plataforma cubre este material y se recomienda para principiantes en computaci\xf3n cu\xe1ntica."]}),"\n",(0,s.jsx)(a.h2,{id:"the-story-of-computation",children:"La historia de la computaci\xf3n"}),"\n",(0,s.jsxs)(a.p,{children:["La computaci\xf3n cu\xe1ntica es una emocionante nueva tecnolog\xeda en una fase temprana de desarrollo -- pero es solo un cap\xedtulo en una historia que se remonta miles de a\xf1os.\nEs la historia de la ",(0,s.jsx)(a.em,{children:"computaci\xf3n"})," y sus conexiones multifac\xe9ticas con el ",(0,s.jsx)(a.em,{children:"mundo f\xedsico"}),"."]}),"\n",(0,s.jsx)(a.h3,{id:"computing-devices-since-ancient-times",children:"Dispositivos de c\xe1lculo desde la antig\xfcedad"}),"\n",(0,s.jsxs)(a.p,{children:["Desde la antig\xfcedad, los seres humanos hemos necesitado realizar ",(0,s.jsx)(a.em,{children:"c\xe1lculos"})," -- o, en otras palabras, procesar informaci\xf3n seg\xfan reglas y restricciones determinadas -- para facilitar la comunicaci\xf3n, la construcci\xf3n, el comercio, la ciencia y otros aspectos de nuestras vidas.\nHemos recurrido al mundo f\xedsico en busca de ayuda y, mediante ingeniosos descubrimientos, hemos construido dispositivos que nos ayudan a calcular."]}),"\n",(0,s.jsxs)(a.p,{children:["Hace mucho tiempo, dispositivos hechos de madera, hueso y nudos almacenaban informaci\xf3n y facilitaban los c\xe1lculos.\nLos dispositivos mec\xe1nicos, construidos con palancas, engranajes y otras m\xe1quinas, evolucionaron desde los primeros relojes astron\xf3micos hasta calculadoras y dispositivos de c\xe1lculo sofisticados como los analizadores diferenciales, que resolv\xedan ecuaciones usando ruedas y discos giratorios.\nIncluso la tecnolog\xeda de la escritura ha desempe\xf1ado un papel importante en esta historia, al permitir que los ",(0,s.jsx)(a.em,{children:"seres humanos"})," realizaran c\xe1lculos que de otro modo no habr\xedan podido hacer."]}),"\n",(0,s.jsx)(a.p,{children:"Cuando pensamos en computadores hoy en d\xeda, tendemos a pensar en computadores digitales electr\xf3nicos.\nPero esa es en realidad una tecnolog\xeda bastante reciente: los computadores digitales electr\xf3nicos se construyeron por primera vez en la d\xe9cada de 1940.\n(En contraste, se cree que el \xe1baco sumerio fue inventado en alg\xfan momento entre el 2700 y el 2300 a. C.)\nLa tecnolog\xeda ha avanzado dram\xe1ticamente desde entonces y los computadores son ahora ubicuos.\nSe encuentran en hogares, lugares de trabajo y en los veh\xedculos que nos transportan entre ellos, y muchos de nosotros los llevamos a todas partes."}),"\n",(0,s.jsxs)(a.p,{children:["Tambi\xe9n tenemos ",(0,s.jsx)(a.em,{children:"supercomputadores"}),", que son grandes colecciones de procesadores cl\xe1sicos potentes conectados en paralelo.\nSon algunas de las mejores herramientas que la humanidad ha construido jam\xe1s para resolver problemas dif\xedciles, y su rendimiento y fiabilidad siguen avanzando.\nPero aun as\xed, hay problemas computacionales importantes que incluso estos gigantes nunca podr\xe1n resolver debido a la dificultad computacional inherente de estos problemas."]}),"\n",(0,s.jsx)(a.h3,{id:"connections-to-the-physical-world",children:"Conexiones con el mundo f\xedsico"}),"\n",(0,s.jsxs)(a.p,{children:["Los computadores tienen muchos usos.\nUn uso importante de los computadores es ",(0,s.jsx)(a.em,{children:"aprender"})," sobre el mundo f\xedsico y obtener una mejor comprensi\xf3n de sus patrones.\nLos usos hist\xf3ricos en esta categor\xeda incluyeron la predicci\xf3n de eclipses y mareas, la comprensi\xf3n del movimiento de los cuerpos astron\xf3micos y (en tiempos m\xe1s recientes) la modelaci\xf3n de explosiones.\nHoy en d\xeda, dif\xedcilmente existe un laboratorio de f\xedsica en el mundo sin un computador."]}),"\n",(0,s.jsxs)(a.p,{children:["De manera m\xe1s general, la f\xedsica y la computaci\xf3n siempre han estado entrelazadas.\nLa computaci\xf3n no puede existir en el vac\xedo: la informaci\xf3n requiere un medio, y para calcular debemos utilizar el mundo f\xedsico de alguna manera.\nRolf Landauer, un cient\xedfico inform\xe1tico (y empleado de IBM), reconoci\xf3 hace d\xe9cadas que la informaci\xf3n es f\xedsica y solo existe a trav\xe9s de una representaci\xf3n f\xedsica.\nEl ",(0,s.jsx)(a.em,{children:"principio de Landauer"})," establece una conexi\xf3n entre la informaci\xf3n y las leyes de la termodin\xe1mica, pero en realidad hay muchas conexiones."]}),"\n",(0,s.jsx)(a.p,{children:"Comprender el mundo f\xedsico es el objetivo de la f\xedsica como disciplina, pero en realidad es una calle de doble sentido.\nA trav\xe9s de nuestra comprensi\xf3n del mundo f\xedsico podemos aprovechar nuevas tecnolog\xedas que nos ayudan a calcular, y a trav\xe9s de ellas seguimos aprendiendo sobre el mundo f\xedsico -- nos impulsamos mutuamente, tirando de la f\xedsica y la tecnolog\xeda computacional hacia arriba."}),"\n",(0,s.jsx)(a.h3,{id:"moores-law",children:"Ley de Moore"}),"\n",(0,s.jsx)(a.p,{children:"La ley de Moore es la observaci\xf3n de que el n\xfamero m\xe1ximo de transistores en un circuito integrado se duplica aproximadamente cada 2 a\xf1os.\nEn las \xfaltimas 5 d\xe9cadas, no solo hemos observado esta tendencia, sino que tambi\xe9n hemos cosechado sus frutos.\nCon m\xe1s transistores en un chip, podemos realizar c\xe1lculos m\xe1s complejos y hacerlo m\xe1s r\xe1pido.\nEsa es la raz\xf3n por la que los computadores se han vuelto cada vez m\xe1s potentes con el tiempo."}),"\n",(0,s.jsx)(a.p,{children:'Sin embargo, la "ley" de Moore se acerca inevitablemente a su fin.\nLos expertos no est\xe1n de acuerdo sobre cu\xe1ndo suceder\xe1 eso, y algunos argumentan que ya ha sucedido.\nPero sabemos con certeza que inevitablemente debe terminar, porque hay un l\xedmite te\xf3rico para la miniaturizaci\xf3n de los componentes de c\xe1lculo.\n\xa1No podemos hacer un transistor m\xe1s peque\xf1o que un \xe1tomo!\nAunque esto pueda sonar exagerado, ese es el muro al que nos dirigimos.'}),"\n",(0,s.jsx)(a.p,{children:'La soluci\xf3n no es renunciar y decir: "Bueno, esto es lo mejor que podemos lograr."\nEso va en contra de la naturaleza humana.\nEn su lugar, debemos explorar el mundo f\xedsico en busca de nuevas herramientas de c\xe1lculo, y aqu\xed es donde entra la computaci\xf3n cu\xe1ntica.'}),"\n",(0,s.jsx)(a.h2,{id:"quantum-computing",children:"Computaci\xf3n cu\xe1ntica"}),"\n",(0,s.jsx)(a.h3,{id:"quantum-mechanics-and-computation",children:"Mec\xe1nica cu\xe1ntica y computaci\xf3n"}),"\n",(0,s.jsx)(a.p,{children:"La mec\xe1nica cu\xe1ntica fue descubierta a principios del siglo XX y ya ha desempe\xf1ado un papel importante en la computaci\xf3n.\nDe hecho, nuestra comprensi\xf3n de la mec\xe1nica cu\xe1ntica hizo posible en parte los computadores modernos.\nSin la mec\xe1nica cu\xe1ntica, por ejemplo, ser\xeda dif\xedcil imaginar que se hubiera inventado el disco duro de estado s\xf3lido."}),"\n",(0,s.jsx)(a.h3,{id:"quantum-computing-in-theory",children:"Computaci\xf3n cu\xe1ntica en la teor\xeda"}),"\n",(0,s.jsx)(a.p,{children:"Cuando Richard Feynman propuso por primera vez el concepto de un computador cu\xe1ntico en 1982, se centr\xf3 en la simulaci\xf3n de sistemas de mec\xe1nica cu\xe1ntica.\nLos c\xe1lculos necesarios para ello parec\xedan ser demasiado dif\xedciles para los computadores ordinarios -- pero quiz\xe1s los sistemas podr\xedan ser emulados directamente con un computador que operara seg\xfan una descripci\xf3n mec\xe1nico-cu\xe1ntica del mundo."}),"\n",(0,s.jsx)(a.p,{children:"Hoy, ese es uno de los caminos m\xe1s prometedores para la computaci\xf3n cu\xe1ntica.\nSeg\xfan nuestro mejor entendimiento, la naturaleza no es cl\xe1sica -- es mec\xe1nico-cu\xe1ntica.\nPor lo tanto, los computadores cu\xe1nticos podr\xedan ser herramientas valiosas para comprenderla.\nLos computadores cl\xe1sicos, por otro lado, solo pueden aproximar lo que realmente sucede en la naturaleza, y en algunos casos estas aproximaciones son muy limitadas."}),"\n",(0,s.jsx)(a.p,{children:"Una forma de pensar en esto es mediante una analog\xeda con los t\xfaneles de viento.\nLa din\xe1mica de fluidos es notoriamente dif\xedcil de simular y predecir matem\xe1ticamente.\nEs, por ejemplo, demasiado costoso e impr\xe1ctico simular un autom\xf3vil contra el viento, por lo que los fabricantes de autom\xf3viles construyen t\xfaneles con viento soplando y conducen los autom\xf3viles a trav\xe9s de ellos para probar su rendimiento.\nEs decir, generan viento en lugar de simularlo.\nConstruir un computador cu\xe1ntico para estudiar el mundo f\xedsico puede compararse, de alguna manera, con construir un t\xfanel de viento para estudiar el efecto del viento en los autom\xf3viles.\nLos computadores cu\xe1nticos pueden emular las leyes de la naturaleza a nivel molecular directamente, ya que act\xfaan de acuerdo con esas leyes --\nesto significa que emulan la naturaleza en lugar de simularla mediante f\xf3rmulas y c\xe1lculos."}),"\n",(0,s.jsxs)(a.p,{children:["Otros siguieron las ideas de Feynman -- y vincularon estas ideas con una teor\xeda de la ",(0,s.jsx)(a.em,{children:"informaci\xf3n cu\xe1ntica"})," que ya estaba en desarrollo.\nNaci\xf3 el campo de la ",(0,s.jsx)(a.em,{children:"informaci\xf3n y computaci\xf3n cu\xe1ntica"}),".\nDesde entonces se ha convertido en un rico campo de investigaci\xf3n multidisciplinaria, y numerosas ventajas de la informaci\xf3n y computaci\xf3n cu\xe1ntica sobre la cl\xe1sica han sido identificadas en una variedad de \xe1reas ",(0,s.jsx)(a.em,{children:"te\xf3ricas"})," de comunicaci\xf3n, computaci\xf3n y criptograf\xeda."]}),"\n",(0,s.jsx)(a.h3,{id:"quantum-computing-in-practice",children:"Computaci\xf3n cu\xe1ntica en la pr\xe1ctica"}),"\n",(0,s.jsx)(a.p,{children:"En t\xe9rminos pr\xe1cticos, se necesitan dos cosas para convertir este tipo de ventajas te\xf3ricas en ventajas reales: los dispositivos en s\xed mismos y los m\xe9todos para desbloquear su potencial."}),"\n",(0,s.jsx)(a.p,{children:"A diferencia de los computadores cl\xe1sicos, nadie lleva un computador cu\xe1ntico en el bolsillo.\nHasta hace poco, si quer\xedas experimentar con un computador cu\xe1ntico, ten\xedas que construir y mantener uno t\xfa mismo\n(normalmente en un oscuro laboratorio de s\xf3tano universitario), y en el mejor de los casos tendr\xedas unos pocos qubits muy ruidosos.\nEso ya no es as\xed.\nEn 2016, IBM Quantum\xae puso a disposici\xf3n el primer procesador cu\xe1ntico en la nube.\nTen\xeda solo 5 qubits y tasas de error relativamente altas, pero hemos recorrido un largo camino desde entonces.\nResumiremos el estado actual de la tecnolog\xeda en una secci\xf3n m\xe1s adelante."}),"\n",(0,s.jsx)(a.p,{children:"Adem\xe1s de construir computadores cu\xe1nticos, tambi\xe9n necesitamos desarrollar m\xe9todos para usarlos de manera efectiva.\nMientras que los avances te\xf3ricos en algoritmos y protocolos cu\xe1nticos sugieren un fuerte potencial, el desaf\xedo de encontrar usos pr\xe1cticos para la computaci\xf3n cu\xe1ntica a\xfan est\xe1 por delante.\nLos computadores cu\xe1nticos de hoy a\xfan no pueden realizar c\xe1lculos tolerantes a fallos que ser\xedan necesarios para convertir las ventajas te\xf3ricas conocidas en ventajas pr\xe1cticas.\nPero est\xe1n m\xe1s all\xe1 del alcance de las simulaciones por computador cl\xe1sicas, y podemos apuntar a aprovechar ese hecho para obtener rendimiento computacional."}),"\n",(0,s.jsx)(a.p,{children:"Con estos avances, tenemos una nueva herramienta para la computaci\xf3n, y depende de nosotros descubrir qu\xe9 podemos hacer con ella."}),"\n",(0,s.jsx)(a.h3,{id:"potential-applications",children:"Aplicaciones potenciales"}),"\n",(0,s.jsx)(a.p,{children:"No se espera que la computaci\xf3n cu\xe1ntica sea \xfatil para investigar c\xf3mo se comportan los autom\xf3viles en el viento.\nPero hay otros procesos f\xedsicos -- como los involucrados en el dise\xf1o de bater\xedas o en ciertas reacciones qu\xedmicas -- donde la capacidad de un computador cu\xe1ntico para emular la naturaleza podr\xeda llevar a una ventaja cu\xe1ntica.\nDe manera m\xe1s general, hay muchos problemas que son demasiado dif\xedciles o costosos incluso para los supercomputadores m\xe1s avanzados, incluidos problemas que son muy relevantes para nuestra sociedad.\nLa computaci\xf3n cu\xe1ntica puede no ofrecer soluciones para todos, pero para algunos podr\xeda ofrecerlas."}),"\n",(0,s.jsx)(a.p,{children:"Las siguientes tres \xe1reas de aplicaci\xf3n representan objetivos en el \xe1mbito de la computaci\xf3n cu\xe1ntica ruidosa, antes de la implementaci\xf3n de la correcci\xf3n cu\xe1ntica de errores y la tolerancia a fallos."}),"\n",(0,s.jsxs)(a.ul,{children:["\n",(0,s.jsx)(a.li,{children:"Optimizaci\xf3n"}),"\n",(0,s.jsx)(a.li,{children:"Simulaci\xf3n de la naturaleza"}),"\n",(0,s.jsx)(a.li,{children:"Encontrar estructura en datos (incluyendo aprendizaje autom\xe1tico)"}),"\n"]}),"\n",(0,s.jsx)(a.p,{children:"Discutiremos estos temas con m\xe1s detalle m\xe1s adelante en el curso."}),"\n",(0,s.jsx)(a.h3,{id:"state-of-the-technology",children:"Estado de la tecnolog\xeda"}),"\n",(0,s.jsx)(a.p,{children:"Construir computadores cu\xe1nticos es un desaf\xedo tecnol\xf3gico dif\xedcil, y solo han pasado 8 a\xf1os desde que peque\xf1os computadores cu\xe1nticos est\xe1n disponibles p\xfablicamente.\nEn esos 8 a\xf1os, hemos logrado avances en muchos frentes."}),"\n",(0,s.jsxs)(a.p,{children:["Numerosos procesadores cu\xe1nticos de IBM son ahora accesibles a trav\xe9s de la nube, todos los cuales tienen m\xe1s de 100 qubits.\nPero no es solo el tama\xf1o de los procesadores lo que importa -- esa es solo una m\xe9trica que nos interesa.\nLa calidad de las puertas tambi\xe9n ha mejorado dram\xe1ticamente, y tambi\xe9n hemos introducido m\xe9todos para reducir y mitigar los errores inherentes a los sistemas de mec\xe1nica cu\xe1ntica, incluso mientras trabajamos hacia la creaci\xf3n de sistemas tolerantes a fallos.\nTres m\xe9tricas fundamentales -- ",(0,s.jsx)(a.em,{children:"tama\xf1o"}),", ",(0,s.jsx)(a.em,{children:"calidad"})," y ",(0,s.jsx)(a.em,{children:"velocidad"})," -- son cruciales para rastrear las mejoras de rendimiento."]}),"\n",(0,s.jsxs)(a.ul,{children:["\n",(0,s.jsxs)(a.li,{children:["\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Tama\xf1o."})," M\xe1s qubits son obviamente mejores, pero solo si el aumento en n\xfamero no perjudica el rendimiento\n(lo cual puede ocurrir). De hecho, queremos m\xe1s qubits de alta calidad que no interfieran entre s\xed por diafon\xeda\ncuando no queremos que lo hagan. La forma en que los qubits est\xe1n conectados entre s\xed tambi\xe9n es importante, y\ndeterminar cu\xe1l es la mejor forma de hacerlo representa un desaf\xedo para los circuitos de qubits superconductores."]}),"\n"]}),"\n",(0,s.jsxs)(a.li,{children:["\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Calidad."})," Otra m\xe9trica importante que observamos para rastrear las mejoras de rendimiento a lo largo del tiempo es la\nfidelidad de las puertas de 2 qubits. Las puertas que operan en qubits individuales no son tan propensas a errores como las puertas de 2 qubits, que por lo tanto\nson la mayor preocupaci\xf3n. (Las puertas de 2 qubits tambi\xe9n son cruciales porque son responsables de generar el entrelazamiento entre los qubits,\nque se cree que es uno de los fen\xf3menos f\xedsicos que otorga a la computaci\xf3n cu\xe1ntica su potencia.)"]}),"\n"]}),"\n",(0,s.jsxs)(a.li,{children:["\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Velocidad."})," Por \xfaltimo, est\xe1 la velocidad y la eficiencia. En resumen, el tiempo dedicado a ejecutar un programa\n(incluyendo tanto las partes cu\xe1nticas como las cl\xe1sicas) debe ser lo m\xe1s corto posible."]}),"\n"]}),"\n"]}),"\n",(0,s.jsx)(a.h2,{id:"conclusion",children:"Conclusi\xf3n"}),"\n",(0,s.jsx)(a.p,{children:"Es realmente un momento emocionante para trabajar en el campo de la computaci\xf3n cu\xe1ntica: por primera vez en la historia, podemos comenzar a explorar un dominio computacional que est\xe1 m\xe1s all\xe1 de la computaci\xf3n cl\xe1sica."}),"\n",(0,s.jsx)(a.p,{children:"T.J. Watson predijo famosamente una vez que habr\xeda un mercado mundial para solo unos pocos computadores.\nPuede que nos riamos ahora de lo equivocado que estaba -- pero al hacerlo, debemos reconocer que tenemos la ventaja de la retrospectiva.\nY tambi\xe9n deber\xedamos reconocer que los seres humanos tendemos a subestimar enormemente el potencial de las tecnolog\xedas futuras.\nAhora que nos toca a nosotros y asumimos roles como pioneros tempranos de la computaci\xf3n cu\xe1ntica, deber\xedamos tener eso en mente."}),"\n",(0,s.jsx)(a.p,{children:"La computaci\xf3n cu\xe1ntica a menudo se contrasta con la computaci\xf3n cl\xe1sica como algo claramente diferente y en competencia con ella.\nPero desde una perspectiva m\xe1s amplia, podemos ver la computaci\xf3n cu\xe1ntica simplemente como otro cap\xedtulo en una larga historia.\nEst\xe1 en nuestra naturaleza como seres humanos buscar nuevas formas de calcular y aprovechar el poder que el mundo natural nos ofrece para ello.\nLo hemos estado haciendo durante siglos.\nLa computaci\xf3n cu\xe1ntica nos ofrece una nueva herramienta en este empe\xf1o, y depende de nosotros descubrir c\xf3mo podemos aprovechar el poder que nos brinda."})]})}function d(e={}){const{wrapper:a}={...(0,c.R)(),...e.components};return a?(0,s.jsx)(a,{...e,children:(0,s.jsx)(u,{...e})}):u(e)}},28453(e,a,o){o.d(a,{R:()=>i,x:()=>r});var n=o(96540);const s={},c=n.createContext(s);function i(e){const a=n.useContext(c);return n.useMemo(function(){return"function"==typeof e?e(a):{...a,...e}},[a,e])}function r(e){let a;return a=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:i(e.components),n.createElement(c.Provider,{value:a},e.children)}}}]);